def handoff_order(tasks: dict[str, list[str]]) -> list[str]:
    pending = {name: set(deps) for name, deps in tasks.items()}
    order: list[str] = []
    while pending:
        ready = sorted(name for name, deps in pending.items() if not deps)
        if not ready:
            raise ValueError('cyclic task graph')
        for name in ready:
            order.append(name)
            pending.pop(name)
        for deps in pending.values():
            deps.difference_update(ready)
    return order

def failure_reason(status: str, reason: str | None) -> str | None:
    if status == 'success':
        return None
    if reason:
        return reason
    if status == 'timed_out':
        return 'timeout'
    return 'unknown'
